132	// selectLedgerData 从源台账中抽取所选资产及其全部工单、请求绑定、履历、
133	// 保养计划、备件领用记录与附件索引，组成一份独立的新台账数据。编号、序号、
134	// 计数器与全部业务内容原样保留，不做任何重编号。返回的切片均为新分配，
135	// 修改结果不会影响源台账。第三返回值为按登记履历序号排序的所选附件索引。
136	func selectLedgerData(src *store, ids []string) (*storeData, map[string]bool, []*Attachment) {
137		selected := map[string]bool{}
138		for _, id := range ids {
139			selected[id] = true
