// hasSubmission 报告工单是否曾提交过维修（含已退回的提交）。
func (s *store) hasSubmission(ticketID string) bool {
    for _, e := range s.data.Events {
        if e.TicketID == ticketID && e.Kind == eventSubmit {
            return true
        }
    }
    return false
}

// currentSubmission 返回工单当前待验收提交的履历序号与维修结果。
// 整库一致性已保证待验收工单恰有一个未被验收处理的提交。
func (s *store) currentSubmission(ticketID string) (int, string, bool) {
    processed := map[int]bool{}
    best := 0
    result := ""
    for _, e := range s.data.Events {
        if e.TicketID != ticketID { continue }
        switch e.Kind {
        case eventAccept:
            processed[e.TargetSeq] = true
        case eventSubmit:
            if e.Seq > best { best = e.Seq; result = e.Content }
        }
    }
    if best == 0 || processed[best] { return 0, "", false }
    return best, result, true
}
