func (s *store) partsOf(ticketID string) []*PartWithdrawal {
	seqs := s.withdrawSeqs()
	out := make([]*PartWithdrawal, 0)
	for _, p := range s.data.Parts {
		if p.TicketID == ticketID {
			out = append(out, p)
		}
