// replayAsset 按全库履历序号重放资产在截止序号 cutoff 处的状态。调用前
// openStore 已完成整库一致性检查；assetID 由调用方确认存在。本方法只读，
// 不修改任何业务记录。
func (s *store) replayAsset(assetID string, cutoff int) *replaySnapshot {
