	for _, e := range s.data.Events {
		if e.AssetID == assetID && e.Seq <= cutoff {
			events = append(events, e)
		}
	}
	sort.SliceStable(events, func(i, j int) bool { return events[i].Seq < events[j].Seq })

	var openID string
	openStatus := ""
	assignee := ""
	submitSeq := 0
	submitResult := ""
	deactivated := false
	core := newMaintCore()
	for _, e := range events {
		switch e.Kind {
		case eventReport:
			// 整库一致性已保证同一资产前一张工单终结后才会产生新报修。
			openID = e.TicketID
			openStatus = ticketOpen
			assignee = ""
			submitSeq = 0
			submitResult = ""
		case eventAssign:
			if e.TicketID == openID {
				assignee = e.To
			}
		case eventSubmit:
			if e.TicketID == openID {
				openStatus = ticketPending
				submitSeq = e.Seq
				submitResult = e.Content
			}
		case eventAccept:
			// 退回恢复未关闭；通过后紧随的关闭履历会终结工单，截止落在两者
			// 之间时保持待验收（后续关闭不提前生效）。
			if e.TicketID == openID && e.Decision == decisionReject {
				openStatus = ticketOpen
				submitSeq = 0
				submitResult = ""
			}
		case eventClose, eventCancel:
			if e.TicketID == openID {
				openID = ""
				openStatus = ""
				assignee = ""
				submitSeq = 0
				submitResult = ""
			}
		case eventRelocate:
			snap.location = e.To
		case eventDeactivate:
			deactivated = true
		case eventReactivate:
			deactivated = false
		}
		// 保养方案段推进与停用状态由共享规则核心完成；停用只影响是否允许
		// 新完成登记（数据一致性已保证），不影响方案与到期日的展示。
		_ = core.apply(e)
	}

	switch {
	case deactivated:
		snap.status = statusDeactivated
	case openID != "":
		snap.status = statusRepairing
	default:
		snap.status = statusAvailable
	}
	if openID != "" {
		snap.openTicket = &replayTicket{
			id:             openID,
			assignee:       assignee,
			reportLocation: s.locationAtSeq(assetID, s.ticketReportSeq(assetID, openID, cutoff)),
			status:         openStatus,
			submitSeq:      submitSeq,
			submitResult:   submitResult,
		}
	}
	if content, firstDue, interval, nextDue, created := core.derived(assetID); created {
		snap.plan = &replayPlan{
			content:  content,
			firstDue: firstDue,
			interval: interval,
			nextDue:  nextDue,
		}
	}
	return snap
