		t.Fatalf="有效待验收旧库应能加载: %v", err)
	}
	seq, result, ok := s.currentSubmission("T0001")
	if !ok || seq != 7 || result != "已更换搓纸轮" {
		t.Fatalf="当前提交 = (%d, %q, %v)", seq, result, ok)
	}
	tk, asset, err := s.acceptSubmission("T0001", 7, decisionApprove, "复核通过")
